template<class Scalar>
std::array<Scalar, 2> displacement(Scalar x, Scalar y, Scalar t)
{
    using std::sin; using std::cos; using std::exp; using std::pow; using std::sqrt;
    const Scalar s0 = std::sqrt(5)*t*std::exp((1.0/2.0)*x + (1.0/4.0)*y)*std::sin(M_PI*x)*std::sin(M_PI*y);
    return {(1800.0/52663.0)*s0, (900.0/52663.0)*s0};
}

template<class Scalar>
Scalar fluidPressure(Scalar x, Scalar y, Scalar t)
{
    using std::sin; using std::cos; using std::exp; using std::pow; using std::sqrt;
    return t*std::exp(-1.0/2.0*y)*std::sin(M_PI*x)*std::sin(M_PI*y);
}

template<class Scalar>
Scalar solidPressure(Scalar x, Scalar y, Scalar t, Scalar K)
{
    using std::sin; using std::cos; using std::exp; using std::pow; using std::sqrt;
    const Scalar s0 = M_PI*y;
    const Scalar s1 = std::sin(s0);
    const Scalar s2 = std::sqrt(5);
    const Scalar s3 = std::exp((1.0/2.0)*x + (1.0/4.0)*y);
    const Scalar s4 = M_PI*x;
    const Scalar s5 = s2*s3*t*std::sin(s4);
    const Scalar s6 = s1*s5;
    const Scalar s7 = M_PI*s5*std::cos(s0);
    const Scalar s8 = M_PI*s1*s2*s3*t*std::cos(s4);
    return (1.0/2.0)*K*((1.0/2773391569.0)*std::pow(1125*s6 + 900*s7 + 1800*s8 + 52663, 2) - 1)/((1125.0/52663.0)*s6 + (900.0/52663.0)*s7 + (1800.0/52663.0)*s8 + 1);
}

